// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"¡Hola! Spanish is spoken by over 500 million people. Let's start with how to say hello and introduce yourself.","blocks":[{"t":"p","text":"Greetings change with the time of day: buenos días (good morning), buenas tardes (good afternoon), buenas noches (good evening/night). Hola works anytime."},{"t":"key","text":"Use tú (informal \"you\") with friends and family, and usted (formal \"you\") with adults you don't know well, teachers and elders."},{"t":"p","text":"Introducing yourself:"},{"t":"list","items":["¿Cómo te llamas? (What's your name? informal) — Me llamo Ana.","¿Cómo estás? (How are you?) — Bien, gracias. ¿Y tú?","Mucho gusto. (Nice to meet you.)","¿De dónde eres? (Where are you from?) — Soy de México."]},{"t":"p","text":"Saying goodbye: adiós, hasta luego (see you later), hasta mañana (see you tomorrow)."}]},{"say":"Spanish is very phonetic: words are pronounced the way they're spelled. Learn the sounds and you can read anything!","blocks":[{"t":"p","text":"Spanish vowels always make the same sound: a (ah), e (eh), i (ee), o (oh), u (oo)."},{"t":"key","text":"Special letters and sounds: ñ sounds like \"ny\" (año = year), ll and y usually sound like \"y\" (llamar), rr is rolled (perro = dog), h is silent (hola), and j sounds like an English h (jugar)."},{"t":"p","text":"Stress rules: words ending in a vowel, n or s are stressed on the second-to-last syllable (casa, hablan). Other words are stressed on the last syllable (hablar). Written accents (á, é, í, ó, ú) show exceptions: teléfono."},{"t":"p","text":"Punctuation: questions and exclamations begin with upside-down marks: ¿Cómo estás? ¡Qué bien!"}]}],[{"say":"Numbers and dates help you shop, make plans and talk about birthdays. ¡Vamos!","blocks":[{"t":"p","text":"Numbers 1–10: uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve, diez. Then once (11), doce (12), quince (15), veinte (20), treinta (30), cincuenta (50), cien (100)."},{"t":"key","text":"Days of the week (lunes, martes, miércoles, jueves, viernes, sábado, domingo) and months (enero, febrero, marzo…) are NOT capitalized in Spanish."},{"t":"p","text":"To give a date, say the day number before the month: el cinco de mayo (May 5th). The first of the month uses primero: el primero de enero."},{"t":"ex","problem":"How do you say \"Today is Monday, March 14\"?","steps":["Hoy es + day + el + number + de + month"],"answer":"Hoy es lunes, el catorce de marzo."}]},{"say":"¿Qué hora es? (What time is it?) Let's learn to tell time in Spanish.","blocks":[{"t":"key","text":"Use es la una for 1:00 (singular) and son las + number for other hours: son las tres (it's 3:00)."},{"t":"list","items":["Add minutes with y: son las dos y diez (2:10).","Quarter past: y cuarto. Half past: y media. Before the hour: menos (son las cinco menos cuarto = 4:45).","de la mañana (a.m.), de la tarde (afternoon), de la noche (evening)."]},{"t":"p","text":"To say what time something happens, use a la or a las: La clase es a las ocho."},{"t":"ex","problem":"How do you say \"It's 7:30 p.m.\"?","steps":["Hour 7: son las siete; half past: y media; evening: de la noche"],"answer":"Son las siete y media de la noche."}]}],[{"say":"In Spanish, every noun has a gender: masculine or feminine. Articles match that gender.","blocks":[{"t":"key","text":"Most nouns ending in -o are masculine (el libro) and most ending in -a are feminine (la mesa). There are exceptions: el día, el mapa, la mano."},{"t":"p","text":"Articles:"},{"t":"list","items":["Definite (the): el (masculine singular), la (feminine singular), los (masculine plural), las (feminine plural).","Indefinite (a, some): un, una, unos, unas."]},{"t":"p","text":"To make nouns plural, add -s after a vowel (libros) and -es after a consonant (papeles)."},{"t":"ex","problem":"Give the plural with article: \"the pencil\" (el lápiz)","steps":["Ends in z: change z to c and add -es"],"answer":"los lápices"}]},{"say":"Let's describe yourself and your friends. In Spanish, adjectives usually come after the noun and match it.","blocks":[{"t":"key","text":"Adjectives agree in gender and number with the noun they describe: el chico alto, la chica alta, los chicos altos, las chicas altas. Adjectives ending in -e or a consonant don't change for gender: inteligente, popular."},{"t":"p","text":"Use ser to describe characteristics: Soy simpático. Ella es alta."},{"t":"p","text":"Common adjectives: alto/a (tall), bajo/a (short), simpático/a (nice), inteligente (smart), divertido/a (fun), trabajador/a (hardworking), perezoso/a (lazy)."},{"t":"ex","problem":"Describe \"the funny girls\"","steps":["Noun: las chicas (feminine plural)"],"answer":"las chicas divertidas"}]}],[{"say":"Spanish has two verbs for \"to be\": ser and estar. Knowing when to use each is a big step.","blocks":[{"t":"key","text":"Ser is for lasting traits and identity (DOCTOR: Description, Occupation, Characteristic, Time, Origin, Relationship). Estar is for location and temporary states (PLACE: Position, Location, Action in progress, Condition, Emotion)."},{"t":"list","items":["ser: soy, eres, es, somos, sois, son.","estar: estoy, estás, está, estamos, estáis, están."]},{"t":"ex","problem":"Choose ser or estar: \"I am tired\" and \"I am a student\"","steps":["Tired is a temporary condition: estar","Student is an occupation: ser"],"answer":"Estoy cansado. Soy estudiante."},{"t":"oops","text":"\"Estoy aburrido\" means \"I'm bored,\" but \"Soy aburrido\" means \"I'm boring\"!"}]},{"say":"Most Spanish verbs follow regular patterns. Learn three sets of endings and you can use thousands of verbs!","blocks":[{"t":"key","text":"Drop the -ar, -er or -ir from the infinitive and add endings:"},{"t":"list","items":["-ar (hablar): hablo, hablas, habla, hablamos, habláis, hablan.","-er (comer): como, comes, come, comemos, coméis, comen.","-ir (vivir): vivo, vives, vive, vivimos, vivís, viven."]},{"t":"p","text":"The subject pronouns are yo, tú, él/ella/usted, nosotros, vosotros (used in Spain), ellos/ellas/ustedes. Pronouns are often dropped because the ending shows the subject: Hablo español."},{"t":"ex","problem":"Conjugate \"estudiar\" for \"we\"","steps":["Drop -ar: estudi-","Add -amos"],"answer":"estudiamos"}]}],[{"say":"Let's talk about your school day and your family, two topics you'll use all the time.","blocks":[{"t":"p","text":"School vocabulary: la clase, el maestro/la maestra (teacher), las matemáticas, las ciencias, el inglés, la historia, el arte, el horario (schedule)."},{"t":"key","text":"Use tener (to have) for possession and age: tengo, tienes, tiene, tenemos, tenéis, tienen. Tengo quince años = I'm 15 years old."},{"t":"p","text":"Family: la madre, el padre, los padres (parents), el hermano/la hermana, los abuelos, el tío/la tía, el primo/la prima (cousin)."},{"t":"p","text":"Possessive adjectives: mi/mis (my), tu/tus (your), su/sus (his, her, their), nuestro/a (our). Mis hermanos = my siblings."},{"t":"p","text":"Gustar expresses likes: Me gusta la música (one thing). Me gustan los deportes (plural things)."}]},{"say":"¡Buen provecho! Food is a delicious way to practice Spanish. Let's learn to order at a restaurant.","blocks":[{"t":"p","text":"Food words: el desayuno (breakfast), el almuerzo (lunch), la cena (dinner), el pan, el arroz, el pollo, la fruta, las verduras, el agua, la leche, el jugo."},{"t":"key","text":"Polite ordering phrases: Quisiera… (I would like…), ¿Me trae…? (Could you bring me…?), La cuenta, por favor (The check, please)."},{"t":"p","text":"Stem-changing verbs change their vowel in most forms: querer (e→ie: quiero), poder (o→ue: puedo), pedir (e→i: pido). The nosotros form doesn't change: queremos."},{"t":"ex","problem":"Order a chicken with rice and water politely.","steps":["Use quisiera + the food"],"answer":"Quisiera el pollo con arroz y un agua, por favor."}]}]];
export default text;
